import math
    import random
    import time

    LANGUAGE_WRAPPER = 'An explorer must traverse a rectangular grid of {rows} rows and {cols} columns of unit squares. The explorer may begin each attempt at any chosen square in row 1, and may move one square at a time (up, down, left, or right), revisiting squares if desired. Among the middle rows 2 through {rows_minus_1}, exactly {bad_cols} distinct columns each contain a single invisible teleport gate (located at an arbitrary, adversarially chosen middle-row position within that column), while the remaining {safe_cols} columns contain no gate at all. No column contains more than one gate, but a row may contain gates in multiple columns. If the explorer ever steps on a gate, the explorer is immediately returned to the chosen start square and that attempt ends; the location of the touched gate is then perfectly recorded and remembered for all future attempts. Reaching any square in row {rows} ends the process successfully. The total number {bad_cols} of gated columns is known in advance to the explorer. In the worst case over all placements of the gates consistent with these rules, determine the minimal number k of attempts required by an optimal strategy to guarantee success. Output this minimal k.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Choose reasonably sized parameters ensuring at least one safe column and nontrivial difficulty
while True:
    rows = rng.randint(5, 300)  # at least 5 rows, plenty of middle rows
    cols = rng.randint(4, 300)  # at least 4 columns
    # choose bad_cols between 2 and min(cols-1, 80) to avoid trivial cases and keep variety
    max_bad = cols - 1
    if max_bad < 2:
        continue
    upper = min(max_bad, 80)
    bad_cols = rng.randint(2, upper)
    safe_cols = cols - bad_cols
    if safe_cols >= 1 and rows >= 3:
        break
return {
    'rows': rows,
    'cols': cols,
    'bad_cols': bad_cols,
    'rows_minus_1': rows - 1,
    'safe_cols': safe_cols
}

    def verifier(assign):
# Validate domain constraints and compute the unique correct answer
try:
    rows = int(assign['rows'])
    cols = int(assign['cols'])
    bad_cols = int(assign['bad_cols'])
    rows_minus_1 = int(assign['rows_minus_1'])
    safe_cols = int(assign['safe_cols'])
except Exception:
    # Missing or non-integer fields
    return (False, None)

# Basic consistency checks
if rows < 3 or cols < 2:
    # Not enough rows/cols to define middle rows or movement
    return (False, None)
if rows_minus_1 != rows - 1:
    # Derived slot inconsistent
    return (False, None)
if bad_cols < 1 or bad_cols > cols - 1:
    # Must have at least one gated column, but at least one safe column too
    return (False, None)
if safe_cols != cols - bad_cols or safe_cols < 1:
    return (False, None)

# Correctness argument (sketch in comments):
# Upper bound strategy: Maintain the set S of discovered gated columns (initially empty).
# On each of the first bad_cols attempts, pick any column not in S and go straight down that column.
# If it is gated, you will be teleported at its unique gate; record the column, add it to S.
# Because there is at most one gate per column, the failure reveals exactly one new gated column.
# After bad_cols such failures, S equals the full set of bad columns (size bad_cols). On the next attempt,
# pick any column not in S (which is guaranteed safe) and go straight down to succeed. Thus k <= bad_cols + 1.
# Lower bound (adversarial): For any strategy, the adversary can place the gate in each column you first choose
# on the earliest row your path uses that column (feasible since rows can host multiple gates and each column
# has only one gate). Hence each of the first bad_cols distinct columns you try can be forced to fail, and you
# cannot succeed before trying a safe column. Because exactly bad_cols columns are gated, in the worst case
# you will encounter all bad columns first, forcing at least bad_cols + 1 attempts. Therefore k = bad_cols + 1.

answer = bad_cols + 1
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

